struct SegTree {
    int n;
    vector<long long> st, lazy;
    SegTree(int _n=0){ init(_n); }
    void init(int _n){
        n = _n;
        st.assign(4*n+5, 0);
        lazy.assign(4*n+5, 0);
    }
    void apply(int p, int l, int r, long long val){
        st[p] += val * (r - l + 1);
        lazy[p] += val;
    }
    void push(int p, int l, int r){
        if(lazy[p] != 0 && l != r){
            int m = (l+r)/2;
            apply(p<<1, l, m, lazy[p]);
            apply(p<<1|1, m+1, r, lazy[p]);
            lazy[p] = 0;
        }
    }
    void pull(int p){
        st[p] = st[p<<1] + st[p<<1|1];
    }
    void add2(int p, int l, int r, int i, int j, long long val){
        if(i > r || j < l) return;
        if(i <= l && r <= j){
            apply(p, l, r, val);
            return;
        }
        push(p, l, r);
        int m = (l+r)/2;
        add2(p<<1, l, m, i, j, val);
        add2(p<<1|1, m+1, r, i, j, val);
        pull(p);
    }
    long long sum2(int p, int l, int r, int i, int j){
        if(i > r || j < l) return 0;
        if(i <= l && r <= j) return st[p];
        push(p, l, r);
        int m = (l+r)/2;
        return sum2(p<<1, l, m, i, j) + sum2(p<<1|1, m+1, r, i, j);
    }

    void add2(int l, int r, long long val){
        if(l > r) return;
        add2(1, 1, n, l, r, val);
    }
    long long sum2(int l, int r){
        if(l > r) return 0;
        return sum2(1, 1, n, l, r);
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    freopen("growing.inp", "r", stdin);
    freopen("growing.out", "w", stdout);
    int n, q;
    cin >> n >> q;
    vector<vector<int>> adj(n+1);
    for(int i=0;i<n-1;i++){
        int u,v; cin >> v;
        u = i + 2;
        debug(u, v);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    debug(adj);
    vector<long long> init(n+1, 0);
    vector<int> tin(n+1), tout(n+1), parent(n+1);
    tin.assign(n+1, 0);
    tout.assign(n+1, 0);
    parent.assign(n+1, 0);
    int timer = 0;

    vector<pair<int,int>> st;
    st.emplace_back(1, -1);
    parent[1] = 0;
    while(!st.empty()){
        auto &top = st.back();
        int u = top.first;
        int &it = top.second;
        if(it == -1){

            ++timer;
            tin[u] = timer;
            it = 0;
        }
        if(it < (int)adj[u].size()){
            int v = adj[u][it++];
            if(v == parent[u]) continue;
            parent[v] = u;
            st.emplace_back(v, -1);
        } else {

            tout[u] = timer;
            st.pop_back();
        }
    }

    SegTree seg1(n), seg2(n);

    for(int u=1; u<=n; ++u){
        seg2.add2(tin[u], tin[u], init[u]);
    }
    debug(q);
    while(q--) {
        char type;
        cin >> type;
        debug(type);
        if(type == 'A'){
            int k; long long v; cin >> k >> v;
            seg1.add2(tin[k], tin[k], v); 
        } else if(type == 'B'){
            int u; long long v; cin >> u >> v;
            seg2.add2(tin[u], tout[u], v);
        } else if(type == 'C'){
            int x; cin >> x;
            long long sub = seg2.sum2(tin[x], tin[x]); 
            long long path = seg1.sum2(tin[x], tout[x]);  
            cout << (sub + path) << '\n';
        } else {

        }
    }
}